"""Fixed cyclic Polygraphia III: exact round trips and public-practice metric comparison."""
import csv,json,hashlib,math,importlib.util
from collections import Counter
from vs import corpus,ivtff,refcorpus,dsl

N=5000; COLS=(10,24,120); SOURCES=('la_augustine','la_erasmus','la_vulg_daniel'); CONTROL=('la_patrick','la_vulg_esther_a'); OFFSETS=(0,5000,10000)
raw=open('/tmp/voy-piii.csv','rb').read();assert hashlib.sha256(raw).hexdigest()=='fe3f24a46dbc6b655eab8dbbd75addf84ee4a7dbd387ad802af75d02edfe5b4d'
table=list(csv.DictReader(raw.decode('utf-8-sig').splitlines())); alphabet=list(table[0]); allowed=set(alphabet)
for row in table:
 for c in row: row[c]=row[c].strip()
assert all(len(set(row.values()))==len(row) for row in table[:max(COLS)])
pins={e['id']:e for e in refcorpus.pins()}
for b in SOURCES+CONTROL:
 with open(pins[b]['file'],'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==pins[b]['sha256']

def entropy(c):
 n=sum(c.values());return -sum((v/n)*math.log2(v/n) for v in c.values()) if n else 0

def values(words,adj):
 chars=Counter(''.join(words));pairs=Counter((a,b) for w in words for a,b in zip(w,w[1:]));prev=Counter(a for a,b in pairs)
 return {'tokens':len(words),'types':len(set(words)),'word_entropy':entropy(Counter(words)),
  'glyph_entropy':entropy(chars),'glyph_conditional_entropy':entropy(pairs)-entropy(prev),
  'adjacent_pairs':len(adj),'adjacent_edit1_share':sum(dsl._edit1(words[i],words[j]) for i,j in adj)/len(adj)}

def witness(name):
 expected={'zl':'bf5b6d4ac1e3a51b1847a9c388318d609020441ccd56984c901c32b09beccafc','it':'7f27a8b0feed8f6de0a99900df6bf912dd1d295c38e5f830bac8b41c3f536fb5'}
 fn={'zl':'ZL3b-n.txt','it':'IT2a-n.txt'}[name]
 with open('data/raw/'+fn,'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==expected[name]
 _,ev=corpus.split_pages('practice',name);ws=[];adj=[]
 for p in ev:
  for line in p.lines:
   if line.unit!='P':continue
   last=None
   for k,w in enumerate(line.words):
    if ivtff.uncertain(w) or not(w.isascii() and w.isalpha() and w.islower()):last=None;continue
    if len(ws)==N:return ws,adj
    i=len(ws);ws.append(w)
    if last is not None and last[0]==k-1:adj.append((last[1],i))
    last=(k,i)
 assert len(ws)==N
 return ws,adj

def text(b):return ''.join(c for part in refcorpus.blocks_of(b) for c in part if c in allowed)

def encode(plain,n):
 inv=[{word:c for c,word in row.items()} for row in table[:n]]
 enc=[table[i%n][c] for i,c in enumerate(plain)]
 assert ''.join(inv[i%n][w] for i,w in enumerate(enc))==plain
 return enc

def run():
 witnesses={w:witness(w) for w in ('zl','it')}; result={'n':N,'column_counts':COLS,'sources':SOURCES,'offsets':OFFSETS,
  'witnesses':{w:values(*x) for w,x in witnesses.items()},'planted':{},'unknown_key_controls':[]}
 for book in SOURCES:
  plain=text(book);result['planted'][book]={}
  for n in COLS:
   result['planted'][book][str(n)]={}
   for offset in OFFSETS:
    src=plain[offset:offset+N];assert len(src)==N;enc=encode(src,n)
    result['planted'][book][str(n)][str(offset)]={'roundtrip_exact':True,'by_layout':{w:values(enc,pairs) for w,(ws,pairs) in witnesses.items()}}
 # Separately benchmark the existing unknown-key suffix+bigram search, which
 # chooses random row subsets and therefore is not the same planted key.
 spec=importlib.util.spec_from_file_location('unknown','/tmp/voy_piii_unknown.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
 for b in CONTROL:
  for n in COLS:
   for seed in (41,71,103): result['unknown_key_controls'].append(mod.experiment(b,n,'sequential',seed,'real'))
 return result

if __name__=='__main__':print(json.dumps(run(),indent=2))
